const { applyDiscount, quoteTotal } = require("../src/pricing.js");

const discountCases = [
  [1000, 10, 900],
  [500, 0, 500],
  [2000, 50, 1000],
];

let failed = 0;
for (const [cents, percent, want] of discountCases) {
  const got = applyDiscount(cents, percent);
  if (got !== want) {
    console.error(
      `FAIL applyDiscount(${cents}, ${percent}): expected ${want}, got ${got}`,
    );
    failed++;
  }
}

if (quoteTotal([1000, 2000], 10) !== 2700) {
  console.error(`FAIL quoteTotal([1000,2000], 10): expected 2700, got ${quoteTotal([1000, 2000], 10)}`);
  failed++;
}

console.log(`${discountCases.length + 1 - failed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);

