function applyDiscount(cents, percent) {
  return cents - Math.round((cents * percent) / 100);
}

function quoteTotal(lines, percent) {
  return applyDiscount(lines.reduce((a, b) => a + b, 0), percent);
}

module.exports = { applyDiscount, quoteTotal };

